"任何房间：出征多带 {0} 件宝物。契合「防御」：武器：伤害 +{1}%，命中溅射并减速；其它：再多 {2} 名守卫。": "Qualsiasi stanza: porta {0} reliquie in più in spedizione. Affine a «Difesa»: le armi infliggono +{1}% di danni e fanno danni ad area e rallentano all'impatto; le altre ottengono {2} guardie in più.",
"任何房间：出征带回的物资 +{0}%。契合「运势」：物资再 +{1}%，每场战斗初始积分倍率 +{2}。": "Qualsiasi stanza: rifornimenti riportati +{0}%. Affine a «Fortuna»: rifornimenti +{1}% in più, moltiplicatore di punti iniziale +{2} in ogni battaglia.",
"任何房间：出征视野 +{0}，初始积分倍率 +{1}。契合「运势 / 特殊」：出征地图一开始就全亮，积分倍率再 +{2}。": "Qualsiasi stanza: visuale in spedizione +{0}, moltiplicatore di punti iniziale +{1}. Affine a «Fortuna / Speciale»: la mappa della spedizione parte del tutto rivelata, moltiplicatore +{2} in più.",
"任何房间：出征部队攻击 +{0}%。契合「训练」：领袖出征得到的经验 +{1}%。": "Qualsiasi stanza: attacco delle truppe in spedizione +{0}%. Affine a «Addestramento»: EXP del leader in spedizione +{1}%.",
"任何房间：出征部队生命 +{0}%。契合「医疗」：医院回复 +{1}%，领袖每天再回 {2}%。": "Qualsiasi stanza: vita delle truppe in spedizione +{0}%. Affine a «Medicina»: cure dell'ospedale +{1}%, il leader recupera il {2}% in più al giorno.",
"任何房间：图纸掉率 +{0}%。契合「科幻」：基地每天 +{1} 灵魂碎片。": "Qualsiasi stanza: probabilità di progetti +{0}%. Affine a «Fantascienza»: base +{1} Frammenti d'anima al giorno.",
"任何房间：图纸掉率 +{0}%。契合「锻造」：打造时 {1}% 概率多得一件。": "Qualsiasi stanza: probabilità di progetti +{0}%. Affine a «Forgia»: {1}% di probabilità di una reliquia extra forgiando.",
"任何房间：基地每天 +{0} 灵魂碎片。契合「魔法」：基地每天再 +{1} 灵魂碎片。": "Qualsiasi stanza: base +{0} Frammenti d'anima al giorno. Affine a «Magia»: +{1} in più al giorno.",
"任何房间：基地每天 +{0} 物资。契合「后勤」：这个房间自己的效果 ×{1}。": "Qualsiasi stanza: base +{0} rifornimenti al giorno. Affine a «Logistica»: effetto proprio di questa stanza ×{1}.",
"任何房间：基地每天 +{0} 物资，领袖每天获得 {1} 经验。契合「后勤 / 自然」：这个房间自己的效果 ×{2}。": "Qualsiasi stanza: base +{0} rifornimenti al giorno, il leader ottiene {1} EXP al giorno. Affine a «Logistica / Natura»: effetto proprio di questa stanza ×{2}.",
"任何房间：宝物打造费用 -{0}%。契合「锻造 / 武器」：锻造：{1}% 概率品质 +{2}；武器：伤害 +{3}%。": "Qualsiasi stanza: costo di forgiatura delle reliquie -{0}%. Affine a «Forgia / Arma»: forgiando, {1}% di probabilità di qualità +{2}; le armi infliggono +{3}% di danni.",
"任何房间：建造时间减半，建成返还 {0}% 物资。契合「奇观」：返还提高到 {1}%。": "Qualsiasi stanza: tempo di costruzione dimezzato, al termine viene restituito il {0}% dei rifornimenti. Affine a «Meraviglia»: la restituzione sale al {1}%.",
"任何房间：所有防御塔伤害 +{0}%。契合「武器」：射程 +{1}，攻速 +{2}%。": "Qualsiasi stanza: tutte le torri difensive infliggono +{0}% di danni. Affine a «Arma»: gittata +{1}, vel. d'attacco +{2}%.",
