"任何房间：领袖技能冷却少 {0} 个节点。契合「运势」：出征开局多带 {1} 个支援道具（至少转出「史诗」效果）。": "Qualsiasi stanza: ricarica dell'abilità del leader {0} tappe in meno. Affine a «Fortuna»: inizi le spedizioni con {1} oggetti di supporto in più (effetto minimo «Epico»).",
"任何房间：领袖攻击 +{0}%。契合「武器」：伤害 +{1}%，每次攻击放出连锁闪电（跳 {2} 个敌人）。": "Qualsiasi stanza: attacco del leader +{0}%. Affine a «Arma»: danni +{1}%, ogni attacco scatena un fulmine a catena (salta su {2} nemici).",
"任何房间：领袖每天回复 {0}% 生命（不需要医院）。契合「医疗 / 水域」：医院回复 +{1}%；水域武器射程 +{2}。": "Qualsiasi stanza: il tuo leader recupera il {0}% di vita al giorno (senza ospedale). Affine a «Medicina / Acqua»: cure dell'ospedale +{1}%; gittata delle armi d'acqua +{2}.",
"任何房间：领袖每天获得 {0} 经验。契合「生产」：这个房间自己的产出 ×{1}。": "Qualsiasi stanza: il tuo leader ottiene {0} EXP al giorno. Affine a «Produzione»: produzione propria di questa stanza ×{1}.",
"任何房间：领袖每天获得 {0} 经验。契合「训练」：领袖出征得到的经验 +{1}%。": "Qualsiasi stanza: il tuo leader ottiene {0} EXP al giorno. Affine a «Addestramento»: EXP del leader in spedizione +{1}%.",
