"前面是": "Più avanti c'è",
"前面是「墓园」：雾最浓的地方是镇外的墓园，新坟一夜比一夜多。": "Più avanti c'è il Cimitero: la nebbia lì è più fitta e ogni notte ci sono più tombe nuove.",
"前面是「总装车间」：工厂最后造出来的东西，把工厂里的人都装了进去。": "Più avanti c'è il Reparto di assemblaggio: l'ultima cosa costruita dalla fabbrica ci ha chiuso dentro tutti gli operai.",
"前面是「手术室」：院长说手术很成功，病人只是还没醒。": "Più avanti c'è la Sala operatoria: il direttore dice che l'operazione è riuscita, solo che il paziente non si è ancora svegliato.",
"前面是「海底」：港口下面还有一座城，城门是一张嘴。": "Più avanti c'è il Fondale marino: sotto il porto c'è un'altra città, e la sua porta è una bocca.",
"前面是「知识古树」：古树记得森林里发生过的每一件事，它不想再记住别的了。": "Più avanti c'è l'Albero della Conoscenza: ricorda tutto ciò che è accaduto nella foresta e non vuole ricordare nient'altro.",
"前面是「精灵女王」：女王在月池边等了三百年。她说，你就是她等的那个人。": "Più avanti c'è la Regina Elfica: aspetta da trecento anni accanto allo stagno della luna. Dice che sei tu quello che aspettava.",
"前面是「马戏大棚」：大棚里的笑声从来没停过，只是再也没有观众。": "Più avanti c'è il Tendone del circo: le risate lì dentro non si sono mai fermate, solo che non c'è più pubblico.",
